            'header_user_info' => '헤더의 사용자 정보에 표시할 내용을 설정할 수 있습니다. 비워 두면 표시되지 않습니다.',
            'allowed_locales' => '사용자가 오른쪽 위 메뉴, 로그인 페이지, 개인 설정에서 선택할 수 있는 언어입니다. 비어 있으면 설치된 모든 언어입니다. 사이트의 언어는 항상 선택할 수 있습니다.',
