            'api_available' => 'YES로 설정하기 전에 Laravel 키를 생성하십시오. 생성 방법은 <a href="%suse-api" target="_blank">여기<i class="fa fa-external-link"></i></a>를 참조하십시오. YES로 설정하면 API를 사용할 수 있습니다.',
            'outside_api' => 'YES로 설정하면 Exment 최신 버전 알림 등 외부 서버와 통신하는 처리를 실행할 수 있습니다. 데이터 수신만 수행합니다. ※외부 네트워크에 연결할 수 없는 환경에서 사용하는 등 통신을 하지 않는 경우에는 NO로 설정하십시오.',
