            'meili_index' => '통합 인덱스 이름(예: exment_global)입니다. 변경한 후에는 `php artisan exment:meili-index`를 실행하여 다시 구축하십시오.',
            'meili_global_search' => '끄면 Exment 기본 MySQL 검색으로 돌아갑니다.',
