            'meili_dictionary' => '유의어와 불용어로 검색 정확도를 조정합니다. 인덱스 설정만 변경되므로 저장 후 다시 인덱싱할 필요가 없습니다(몇 초 안에 반영).',
            'meili_dictionary_type' => '"유의어" = 같은 의미로 취급하는 단어 그룹입니다. "불용어" = 검색 시 무시하는 단어입니다(조사 등).',
            'meili_dictionary_word' => '유의어 = 그룹의 대표 단어입니다. 불용어 = 무시할 단어입니다(쉼표/줄바꿈으로 여러 개 입력 가능).',
