            'logging_toggle_available' => 'YES로 설정하면 느린 화면 작업을 "시스템 성능 로그"("설정: 시스템" 메뉴)에 기록합니다. 기록 항목은 화면의 URL(검색 등의 값은 숨김), 사용자, 처리 시간, SQL(값은 "?"로 표시)입니다.',
