            'ip_filter' => '통신을 허용할 IP 주소를 설정합니다. 고정 IP(예: 12.3.5.6) 및 범위 지정 형식(예: 123.4.5.0/24, 2001:db8::/32)을 사용할 수 있습니다. 설정하지 않으면 모든 IP 주소를 허용합니다. <br /> 여러 개를 설정하려면 줄바꿈으로 구분하십시오.',
