            'regex_validate' => '(고급 사용자용) 입력 가능한 내용을 정규 표현식으로 설정합니다. 이 항목에 값을 설정하면 위의 "사용 가능 문자" 설정은 무효가 됩니다. 자세한 내용은&nbsp;<a href="%s" target="_blank">여기<i class="fa fa-external-link"></i></a>&nbsp;를 참조하십시오.',
