        'kanban_labels_style_options' => [
            'chip' => '칩(텍스트 포함)',
            'bar' => '색상 막대만',
        ],
        'description_custom_view_columns' => '뷰에 표시할 열을 설정합니다.',
        'description_custom_view_kanban_columns' => '카드에 표시할 열을 설정합니다. "표시 위치"로 카드 안의 어디에 표시할지, "표시 스타일"로 셀 표시 프리셋(태그, 필, 배지 등)을 지정할 수 있습니다. 데이터 목록과 같은 프리셋을 사용하므로 모양을 한 번 정하면 두 화면에서 동일하게 표시됩니다.<br/>※"표시 스타일"을 선택하지 않으면 열 설정을 따르며, 열에도 설정이 없으면 "항목 이름+값"으로 표시합니다.<br/>※"아이콘"에는 Font Awesome 클래스 이름(예: fa-phone)을 입력하십시오. "값:클래스"를 쉼표로 구분하여 나열하면 값마다 다른 아이콘을 사용할 수 있습니다.<br/>※설정하지 않으면 카드에는 제목만 표시됩니다.<br/>※"색상 라벨 열", "기한 열(SLA 타이머)", "배지 열"로 지정한 열은 각각의 위치에 표시되므로 카드 본문에는 중복하여 표시하지 않습니다.',
        'description_custom_view_calendar_columns' => '캘린더에 표시할 날짜 열을 선택합니다.<br/>※"대상 열"에 사용자 정의 열이 표시되지 않으면 <a href="%s" target="_blank">검색 인덱스<i class="fa fa-external-link"></i></a>가 설정되어 있지 않은 것입니다. 링크 대상의 내용을 확인하고 설정하십시오.',
        'description_custom_view_groups' => '뷰를 그룹화하는 키가 되는 열을 설정합니다.<br />※"대상 열"에 사용자 정의 열이 표시되지 않으면 <a href="%s" target="_blank">검색 인덱스<i class="fa fa-external-link"></i></a>가 설정되어 있지 않은 것입니다. 링크 대상의 내용을 확인하고 설정하십시오.',
        'description_custom_view_summaries' => '뷰에 표시할 집계 열을 설정합니다.<br/>※집계 대상은 "ID", "정수", "소수", "통화", "날짜" 열입니다. 데이터 총 건수를 집계하려면 대상 열을 "ID", 집계 유형을 "건수"로 설정하십시오.',
        'description_custom_view_sorts' => '뷰에 표시할 데이터의 정렬(표시 순서)을 설정합니다.<br />※2개 이상 등록하면 데이터가 매우 많은 테이블에서는 성능이 저하될 수 있습니다. "대상 열"에 사용자 정의 열이 표시되지 않으면 <a href="%s" target="_blank">검색 인덱스<i class="fa fa-external-link"></i></a>가 설정되어 있지 않은 것입니다. 링크 대상의 내용을 확인하고 설정하십시오.',
        'description_custom_view_filters' => '뷰에 표시할 조건을 설정합니다.<br/>※이 설정 외에도 로그인 사용자가 권한을 가진 데이터만 표시되도록 데이터를 필터링합니다.<br />※"대상 열"에 사용자 정의 열이 표시되지 않으면 <a href="%s" target="_blank">검색 인덱스<i class="fa fa-external-link"></i></a>가 설정되어 있지 않은 것입니다. 링크 대상의 내용을 확인하고 설정하십시오.',
        'description_custom_view_grid_filters' => '뷰 상단에 표시되는 "필터"에서 선택지로 표시할 열을 지정합니다.<br/>※시스템 기본 항목을 표시하려면 이 목록에 열을 추가하지 마십시오.<br/>※"대상 열"에 사용자 정의 열이 표시되지 않으면 <a href="%s" target="_blank">검색 인덱스<i class="fa fa-external-link"></i></a>가 설정되어 있지 않은 것입니다. 링크 대상의 내용을 확인하고 설정하십시오.',
        'description_custom_view_summary_filters' => '<br/>※이 "필터"는 집계 결과가 아니라 집계 전의 데이터를 좁히기 위한 것입니다.',
        'help' => [
            'custom_view_type' => '시스템 뷰: 이 테이블을 사용하는 모든 사용자가 사용할 수 있는 뷰입니다. 사용자 뷰: 만든 사용자만 사용할 수 있는 뷰입니다.',
            'grid_preset' => '데이터 목록에서 이 열을 선택한 프리셋의 모양으로 표시합니다.<br/>※열 설정보다 우선합니다.<br/>※연필 버튼으로 프리셋을 새로 만들거나 편집할 수 있습니다.',
            'sort_type' => '오름차순(작은 순)으로 정렬할지 내림차순(큰 순)으로 정렬할지 지정합니다.',
            'sort_order_summaries' => '가져올 데이터를 정렬합니다.<br />"그룹 열"과 "집계 열" 중에서 숫자가 작은 순으로 정렬을 실행합니다.',
            'use_view_infobox' => 'YES로 설정하면 뷰 상단에 업무 내용이나 사용자에게 전할 메시지 등을 입력할 수 있는 정보 상자를 설정할 수 있습니다.',
            'view_infobox_title' => '정보 상자에 표시할 제목을 입력하십시오.',
            'view_infobox' => '정보 상자에 표시할 HTML을 입력하십시오. ※이미지와 스크립트는 입력할 수 없습니다.',
            'order' => '사용자 정의 뷰 메뉴 버튼의 표시 순서입니다.',
            'kanban_group_column' => '이 열의 선택지가 칸반의 레인이 됩니다.<br/>※단일 선택 선택지 열만 지정할 수 있습니다. "칸반 레인 생성 방법"이 "워크플로 상태로 만들기"인 경우 이 설정은 사용하지 않습니다.',
            'kanban_swimlane_column' => '이 열의 값마다 보드를 가로 방향으로 나누어 표시합니다.<br/>※지정하지 않으면 나누지 않고 표시합니다.',
            'kanban_editable' => 'YES로 설정하면 카드를 다른 레인으로 끌어다 놓을 때 "칸반 레인으로 사용할 열"의 값을 업데이트합니다.<br/>※데이터 편집 권한이 없는 사용자는 YES여도 끌어다 놓을 수 없습니다.',
            'inline_edit_enabled' => 'NO로 설정하면 이 뷰의 데이터 목록에서 인라인 편집을 사용하지 않습니다. 일괄 편집과 데이터 편집 화면은 이전과 같이 사용할 수 있습니다.<br/>※시스템 설정의 "데이터 목록에서 인라인 편집 사용"이 NO일 때는 YES여도 인라인 편집할 수 없습니다.',
            'kanban_max_count' => '보드에 표시할 데이터의 최대 건수입니다. 건수가 많으면 표시가 느려집니다.',
            'gantt_start_column' => '막대의 시작 위치가 되는 날짜 열입니다.',
            'gantt_end_column' => '막대의 종료 위치가 되는 날짜 열입니다.<br/>※이 날짜가 지났고 진행률이 100 미만인 데이터는 빨간 테두리의 "기한 초과"로 표시됩니다.',
            'gantt_color_column' => '이 열의 값마다 막대 색을 구분합니다.<br/>※색은 열 상세 설정의 "목록 값 색"을 그대로 사용합니다.',
            'gantt_progress_column' => '막대 안에 진행률(%)을 진한 색으로 겹쳐 표시합니다.',
            'gantt_group_column' => '이 열의 값마다 행을 그룹화합니다.<br/>※다른 테이블 참조 열(마일스톤 테이블 등)을 선택하면 참조 대상 테이블의 날짜 열 중 열 이름 또는 열 표시 이름에 "기한", "마감", "due", "deadline", "期限" 등이 포함된 열을 기한으로 하여 ◆ 표시를 합니다. 해당하는 열이 없으면 마지막 날짜 열을 사용합니다.',
            'gantt_parent_column' => '자기 테이블을 참조하는 열을 선택하면 하위 데이터를 상위 데이터 아래에 들여 써서 표시합니다.',
            'gantt_assignee_column' => '사용자 열을 선택하면 각 행에 아바타를 표시합니다.',
            'gantt_max_count' => '차트에 표시할 최대 건수입니다(10~2000, 기본값 500).',
            'kanban_source' => '칸반 레인을 어디에서 만들지 선택합니다.<br/>※선택지 열로 만들기: 해당 열의 선택지가 그대로 레인이 됩니다.<br/>※워크플로 상태로 만들기: 이 테이블에 적용된 워크플로의 상태가 레인이 됩니다. 카드를 이동하면 해당 상태로 진행하는 워크플로 작업 확인 화면이 열리며, 워크플로에서 허용되지 않는 이동은 할 수 없습니다.',
            'kanban_wip_enforce' => '이미 WIP 상한에 도달한 레인에 카드를 놓을 때의 동작을 정합니다.<br/>"허용"은 기존과 같이 헤더만 빨갛게 바뀌고 카드는 이동됩니다.<br/>"확인 후 허용"은 확인 메시지를 표시하고 동의한 경우에만 이동합니다.<br/>"허용 안 함"은 끌어다 놓는 동안 상한에 도달한 레인을 회색으로 표시하고 놓기를 거부합니다.<br/>※WIP 상한을 설정하지 않은 레인에는 영향이 없습니다.<br/>※"최우선(긴급)으로 간주할 값"에 해당하는 카드는 이 제한을 받지 않지만 건수에는 포함되므로, 상한 초과가 헤더에 계속 표시됩니다.',
            'kanban_policies' => '레인 헤더에 그 레인의 규칙을 표시합니다. 표시에 마우스를 올리면 내용이 나타납니다.<br/>예: "테스트 중" 레인에 "테스트 시트의 모든 항목이 승인되면 다음으로"라고 써 두면 다음 단계로 넘어가는 조건을 팀 전원이 볼 수 있습니다.<br/>※대상 레인은 테이블의 선택지(또는 워크플로 상태)에서 선택합니다.<br/>※현재 표시 중인 레인과 일치하지 않는 설정은 무시됩니다.',
            'kanban_wips' => '레인별로 동시에 가질 수 있는 카드 수의 상한을 설정합니다. 대상 레인은 테이블의 선택지(또는 워크플로 상태)에서 선택하며 직접 입력할 필요는 없습니다.<br/>※상한을 초과한 레인은 헤더가 빨갛게 표시됩니다.<br/>※현재 표시 중인 레인과 일치하지 않는 설정은 무시됩니다.<br/>※카드 수로 셀 때는 1~999입니다. 「WIP 상한 계산 기준(숫자 열)」을 지정한 경우에는 그 항목 합계의 상한을 입력합니다(999보다 크게 할 수 있습니다).',
            'kanban_done_keys' => '"완료"로 취급할 레인을 테이블의 선택지에서 선택합니다.<br/>※선택한 레인의 데이터는 기한 카운트를 멈추고 집계 막대의 "완료"로 계산됩니다.<br/>※워크플로 보드에서는 완료로 설정된 상태를 자동으로 완료로 취급하므로 여기에서 지정할 필요가 없습니다.<br/>※현재 표시 중인 레인과 일치하지 않는 설정은 무시됩니다.',
            'kanban_title_column' => '카드 안에 굵은 제목으로 표시할 열입니다.<br/>※지정하면 카드 상단에 데이터의 표시 이름이 링크로 표시됩니다.<br/>※지정하지 않으면 데이터의 표시 이름이 그대로 제목이 됩니다.',
            'kanban_assignee_column' => '담당자를 나타내는 열입니다.<br/>※카드 하단에 아바타와 함께 표시되며, 값이 없는 카드에는 "미할당"이 표시됩니다.<br/>※집계 막대, "미할당만" 필터, 담당자 일괄 변경에서도 사용합니다.<br/>※<b>설정하지 않으면</b> 아바타, 집계 막대의 "미할당", "미할당만" 필터, 담당자 일괄 변경, 카드에서의 담당자 변경, 자동 할당이 표시되지 않습니다. ""내 담당" 판정에 사용할 열"을 별도로 설정하지 않으면 "내 담당" 버튼도 표시되지 않습니다.',
            'kanban_mine_column' => '도구 모음의 "내 담당" 버튼이 어떤 열을 보고 "내 카드"로 판단할지 정합니다.<br/>※지정하지 않으면 담당자 열을 사용합니다. 요청자 열을 지정하면 내가 낸 요청만으로 보드를 좁힐 수 있습니다.<br/>※사용자 및 조직 열 외에, 사용자 열을 하나만 가진 테이블을 참조하는 열도 지정할 수 있습니다(해당 열을 통해 나와 연결된 행을 찾습니다).<br/>※누가 보고 있는지 판단할 수 없는 열(일반 선택지 등)을 지정하면 버튼이 표시되지 않습니다.',
            'kanban_filter_columns' => '필터 패널에 표시할 열을 필요한 것만 선택합니다. 선택한 순서대로 표시됩니다.<br/>※지정하지 않으면 보드가 읽어 들이는 모든 열(그룹화 가능한 열, 담당자, 카드에 표시할 열 등)이 표시되므로, 열이 많은 테이블에서는 좁혀 두는 것을 권장합니다.<br/>※키워드 검색, 그룹화, 스윔레인, 체크박스는 이 설정과 관계없이 항상 표시됩니다.',
            'kanban_limit_column' => '기한(마감)의 날짜 열입니다.<br/>※현재 시각과의 차이에 따라 카드에 "남은 시간", "기한 임박", "기한 초과" 배지를 표시합니다.<br/>※완료로 간주되는 레인의 데이터에는 대신 "달성"이 표시됩니다.<br/>※<b>설정하지 않으면</b> 기한 배지, 집계 막대의 "기한 초과", "기한 초과만" 필터, 카드에서의 기한 변경이 표시되지 않습니다.',
            'kanban_sum_column' => '레인 헤더 아래에 이 숫자 열의 합계를 표시합니다.<br/>예: 금액 열을 선택하면 헤더에 "임원 승인 &yen;34,700,000"처럼 표시되어 그 레인에 머물러 있는 금액을 한눈에 알 수 있습니다.<br/>※표시 전용이며 WIP 상한에는 영향을 주지 않습니다.<br/>※자릿수 구분과 통화 기호는 해당 열의 설정을 따릅니다.<br/>※보드를 필터링하면 화면에 남은 카드만 합계합니다.',
            'kanban_blocked_keys' => '작업이 멈춰 있음을 나타내는 값을 선택합니다. 선택한 값을 가진 카드에는 빨간 테두리와 깃발 표시가 붙고, KPI 행과 필터 패널에 "차단됨"이 추가됩니다.<br/>예: 상태 열의 "보류", "반려" 또는 차단 전용 열의 "예"를 선택합니다.<br/>※보드를 그룹화하는 열과 다른 열이어도 됩니다. 어느 열의 값이든 선택할 수 있습니다.<br/>※진행 중인 작업과 멈춰 있는 작업을 한눈에 구분할 수 있습니다.',
            'kanban_expedite_keys' => '긴급하게 끼어든 최우선 건을 나타내는 값을 선택합니다. 선택한 값을 가진 카드에는 눈에 띄는 테두리가 붙고, 같은 열로 스윔레인을 나눈 경우 해당 레인이 맨 위에 고정됩니다.<br/>예: 우선순위 열의 "긴급"을 선택합니다.<br/>※최우선 카드는 "WIP 상한을 초과하는 이동" 제한을 받지 않습니다(긴급 건은 상한을 초과해도 된다는 일반적인 칸반 방침에 맞춘 것입니다). 건수에는 포함되므로 상한 초과 사실은 화면에 남습니다.<br/>※많은 값을 최우선으로 지정하면 의미가 없어집니다. 1~2개로 한정하십시오.',
            'kanban_hide_keys' => '선택한 값의 열을 보드에 표시하지 않습니다.<br/>예: "완료", "취소"를 선택하면 끝난 작업이 사라지고 진행 중인 작업만 보드에 남습니다.<br/>※숨긴 열의 데이터는 읽어오지 않으므로, 건수가 많은 테이블에서는 이것만으로도 표시가 크게 빨라집니다.<br/>※합계, 평균, KPI 행에도 포함되지 않습니다.<br/>※워크플로 보드에서 숨긴 상태로 진행하면 카드가 보드에서 사라집니다(데이터 자체는 그대로 남습니다).<br/>※"미설정" 열은 숨길 수 없습니다.<br/>※현재 표시 중인 레인과 일치하지 않는 설정은 무시됩니다.',
            'kanban_col_count' => '각 열에서 처음에 읽어오는 카드 수입니다.<br/>0(미입력)이면 기존과 같이 보드 전체에서 최대 표시 건수까지 한 번에 읽어옵니다.<br/>50 등을 입력하면 열마다 50건씩 읽어오고, 열 아래에 "더 보기" 버튼이 표시됩니다.<br/>※이 경우 건수, 합계, 평균 체류 일수, KPI 행은 읽어온 카드가 아니라 테이블 전체를 집계한 값이 됩니다.<br/>※데이터가 수천 건 이상인 경우 이 방식을 권장합니다. 최대 표시 건수의 제한을 받지 않습니다.<br/>※뷰에 설정한 스윔레인으로 나누는 동안에는 각 칸(열 x 레인)의 건수도 테이블 전체를 집계한 값이 됩니다.<br/>※필터, 키워드 검색, 그룹 변경, 또는 뷰가 아닌 화면에서 선택한 스윔레인을 사용하는 경우에는 이미 읽어온 카드만 집계합니다.',
            'kanban_col_age' => '레인 제목 아래에 해당 레인의 카드가 평균 며칠 동안 머물러 있는지 표시합니다.<br/>※어느 단계에서 작업이 쌓이는지(병목) 알 수 있습니다.<br/>※워크플로 보드에서는 해당 상태가 된 시점부터, 그 외에는 마지막 수정 시점부터 계산합니다.',
            'kanban_progress_column' => '카드 제목 아래에 진행률 막대로 표시할 숫자 열입니다(진행률 등).<br/>※0~49%는 파랑, 50~99%는 주황, 100%는 초록으로 표시됩니다.<br/>※값이 비어 있는 카드에는 막대를 표시하지 않습니다.',
            'kanban_progress_max' => '진행률 막대가 100%가 되는 값입니다.<br/>예: 백분율이면 100, 10단계 공정이면 10을 입력합니다.<br/>※미입력 시 100입니다.',
            'kanban_history' => '카드 상세 패널에 워크플로 이력(언제, 누가, 어떤 작업을 했는지)을 표시합니다.<br/>※카드를 열 때 해당 1건만 읽어오므로 보드 표시 속도에는 영향이 없습니다.<br/>※워크플로를 사용하는 테이블에서만 표시됩니다.',
            'kanban_wip_column' => 'WIP 상한을 카드 수가 아니라 이 숫자 열의 합계로 계산합니다.<br/>예: 수량을 선택하면 레인 제목에 "1550/1200"처럼 표시됩니다.<br/>※지정하지 않으면 기존과 같이 카드 수로 계산합니다.<br/>※정수, 소수, 통화 열만 선택할 수 있습니다.',
            'kanban_limit_warn' => '기한까지 남은 시간이 이 시간보다 적은 카드를 노란색(기한 임박)으로 표시합니다.<br/>예: 문의 티켓이면 2, 납기일이면 48(=2일).<br/>※미입력 시 2시간입니다.',
            'kanban_age_steps' => '카드 테두리가 노랑, 주황, 빨강으로 바뀌는 일수를 작은 순서대로 쉼표로 구분하여 3개 입력합니다.<br/>예: 티켓이면 1,2,3, 긴 공정이면 3,7,14.<br/>※오름차순의 숫자 3개가 아니면 1,2,3으로 처리합니다.',
            'kanban_age_column' => '경과 일수를 계산하는 기준 날짜 열입니다(접수일 등).<br/>※경과 일수에 따라 카드 왼쪽 테두리 색이 바뀝니다(1일 노랑, 2일 주황, 3일 이상 빨강).<br/>※요약 막대의 "평균 경과 일수"에도 사용됩니다.',
            'kanban_ai_column' => '추천 담당자를 정하는 데 사용할 열입니다(담당 그룹 등).<br/>※같은 값의 데이터를 가장 많이 담당한 사람을 미할당 카드에 추천합니다.<br/>※이 항목과 "담당자 열"을 모두 설정한 경우에만 "자동 할당" 버튼이 표시됩니다.',
            'kanban_cover_column' => '카드 상단에 커버로 표시할 이미지 열입니다.<br/>※이미지가 없는 데이터는 커버 없이 표시됩니다.<br/>※이미지가 여러 개 저장된 경우 첫 번째 이미지를 사용합니다.<br/>※이미지 자체는 데이터 편집 화면에서 이 열에 업로드합니다.',
            'kanban_cover_fit' => '커버 이미지를 영역에 맞추는 방법입니다.<br/>※"채우기"는 영역 전체를 채우고 넘치는 부분을 잘라냅니다.<br/>※"전체 표시"는 이미지 전체를 표시하며 여백이 생깁니다.',
            'kanban_labels_column' => '카드 상단에 색상 라벨로 표시할 선택 열입니다.<br/>※다중 선택 열도 지정할 수 있으며, 이 경우 모든 값이 각각 라벨로 표시됩니다.<br/>※지정한 열은 필터 패널에도 추가되어, 라벨 중 하나라도 일치하는 카드로 좁힐 수 있습니다.',
            'kanban_labels_style' => '라벨의 모양입니다.<br/>※"칩"은 텍스트가 들어간 작은 라벨, "컬러 바"는 색만 있는 얇은 막대(Trello 스타일)입니다.',
            'kanban_badge_column' => '카드 오른쪽 위에 작은 배지로 표시할 열입니다(건수, 포인트, 번호 등).<br/>※값이 비어 있는 데이터에는 배지를 표시하지 않습니다.',
            'kanban_kpi' => 'YES로 설정하면 보드 위에 건수 요약 막대를 표시합니다.',
            'kanban_quickadd' => 'YES로 설정하면 각 레인에 입력란이 표시되어 Enter 키만으로 데이터를 추가할 수 있습니다.<br/>※입력되는 값은 표시명 열과 해당 레인의 값뿐입니다.',
            'kanban_bulk' => 'YES로 설정하면 Shift+클릭으로 여러 카드를 선택하여 한꺼번에 값을 변경할 수 있습니다.',
            'kanban_editform' => 'YES로 설정하면 카드를 클릭했을 때 해당 데이터의 편집 폼이 보드 위에 열립니다. 저장하면 폼이 닫히고 해당 카드만 다시 표시됩니다.<br/>※편집 권한이 없는 사용자에게는 표시되지 않습니다.<br/>※NO로 설정하면 아래의 "상세 패널" 설정에 따릅니다.',
            'kanban_drawer' => 'YES로 설정하면 카드를 클릭했을 때 오른쪽에 상세 패널이 열립니다.<br/>※NO로 설정하면 데이터 상세 화면으로 이동합니다.<br/>※위의 "편집 폼 열기"도 YES인 경우 클릭 시 편집 폼이 열리고, 상세 패널은 카드 오른쪽 위의 "i" 버튼으로 엽니다.',
            'kanban_position' => '카드 안에서 이 열을 표시할 위치입니다.',
            'kanban_style' => '이 열을 선택한 프리셋 모양으로 카드에 표시합니다.<br/>열 설정보다 우선합니다.<br/>연필 버튼으로 프리셋을 새로 만들거나 편집할 수 있습니다.<br/>선택하지 않으면 열 설정에 따르며, 열에도 설정이 없으면 "항목명 + 값"으로 표시합니다.',
            'kanban_icon' => 'Font Awesome 클래스 이름입니다(예: fa-phone).<br/>선택지마다 다른 아이콘을 지정하려면 "값:클래스" 쌍을 쉼표로 구분하여 입력하십시오.<br/>예: phone:fa-phone,mail:fa-envelope,chat:fa-comments',
        ],
        'column_sort_options' => [
            'asc' => '오름차순',
            'desc' => '내림차순',
        ],
        'group_condition_options' => [
            'y' => '연도별',
            'ym' => '연월별',
            'ymd' => '연월일별',
            'm' => '월별',
            'd' => '일별',
            'w' => '요일별',
        ],
        'align_type_options' => [
            'inherit' => '사용자 정의 열 설정에 맞춤',
            'left' => '왼쪽 정렬',
            'center' => '가운데 정렬',
            'right' => '오른쪽 정렬',
        ],
        'summary_condition_options' => [
            'sum' => '합계',
            'avg' => '평균',
            'count' => '건수',
            'min' => '최솟값',
            'max' => '최댓값',
        ],
        'filter_condition_options' => [
            'eq' => '검색값과 일치',
            'ne' => '검색값과 불일치',
            'like' => '검색값 포함',
            'not-like' => '검색값 미포함',
            'eq-user' => '로그인 사용자와 일치',
            'ne-user' => '로그인 사용자와 불일치',
            'on' => '지정일',
            'on-or-after' => '지정일 이후',
            'on-or-before' => '지정일 이전',
            'today' => '오늘',
            'today-or-after' => '오늘 이후',
            'today-or-before' => '오늘 이전',
            'yesterday' => '어제',
